const auditing=ref(new Set<string>());const checkingGroups=ref(new Set<string>());const groupDeleteBusy=ref(new Set<string>());const sourceOrder=ref<string[]>([]);const draggedSourceId=ref('');const sources=ref<SourceConfig[]>([]);const liveSources=ref<LiveSourceConfig[]>([]);const health=ref<SourceHealth[]>([]);const loading=ref(true);const bulkBusy=ref(false);const error=ref('');const importText=ref('');const importMessage=ref('');const audit=ref<SourceAuditResult|null>(null);const importTab=ref<'config'|'local-live'|'remote-live'>('config');const draft=reactive({name:'',endpoint:'',kind:'T1_JSON' as SourceKind,ext:'',jar:''});const liveDraft=reactive({name:'',url:'',epg:'',userAgent:''});const healthMap=computed(()=>new Map(health.value.map(item=>[item.sourceId,item])));const isExecutable=(kind:SourceKind)=>kind==='T3_JS'||kind==='T3_PY'||kind==='T3_JAR'||kind==='PLUGIN'||kind==='T4_CATVOD';const enabledCount=computed(()=>sources.value.filter(item=>item.enabled).length+liveSources.value.filter(item=>item.enabled).length);const passedCount=computed(()=>[...sources.value,...liveSources.value].filter(item=>healthMap.value.get(item.id)?.ok===true).length);const confirmCount=computed(()=>executableStates.value.filter(item=>item.required&&!item.approved).length);const totalCount=computed(()=>sources.value.length+liveSources.value.length);const enabledPercent=computed(()=>totalCount.value?Math.round(enabledCount.value/totalCount.value*100):0);const passedPercent=computed(()=>totalCount.value?Math.round(passedCount.value/totalCount.value*100):0);const confirmPercent=computed(()=>sources.value.length?Math.round(confirmCount.value/sources.value.length*100):0);const sourceStateBanner=computed(()=>{if(loading.value)return null;if(totalCount.value===0)return{kind:'empty',title:'尚未导入来源',detail:'请从上方导入 TVBox/FongMi 配置、直播列表，或手工添加来源。'};const pendingTrust=sources.value.filter(item=>!item.enabled&&executableStateMap.value.get(item.id)?.required&&!executableStateMap.value.get(item.id)?.approved).length;if(enabledCount.value===0&&pendingTrust)return{kind:'trust',title:'来源等待授权',detail:`有 ${pendingTrust} 个可执行来源保持停用。请逐项导出代码审核、批准该版本后再启用。`};if(enabledCount.value===0)return{kind:'disabled',title:'所有来源均已停用',detail:'可按来源逐个启用，或使用“全部启动”；外部代码必须独立审核授权后才能执行。'};const enabledIds=new Set([...sources.value.filter(item=>item.enabled),...liveSources.value.filter(item=>item.enabled)].map(item=>item.id));const checked=[...enabledIds].map(id=>healthMap.value.get(id)).filter((item):item is SourceHealth=>item!==undefined);const failed=checked.filter(item=>item.ok===false).length;if(checked.length===enabledIds.size&&failed===enabledIds.size)return{kind:'unavailable',title:'已启用来源当前均未通过检查',detail:'这可能是网络、鉴权、规则或远端服务问题。请查看失败原因或重新执行健康检测。'};if(failed)return{kind:'partial',title:`已检查来源中有 ${failed} 个未通过`,detail:`已启用来源已检查 ${checked.length}/${enabledIds.size}，${enabledIds.size-checked.length} 个尚未检查。请查看逐来源结果，未检查不代表不可用。`};return null;});
type GroupKey='api'|'rule'|'spider';const groupMeta:Record<GroupKey,{label:string;description:string}>={api:{label:'接口类来源',description:'CMS XML / JSON / Type4 等声明式接口'},rule:{label:'规则与网盘',description:'XYQ / XBPQ / AList 等规则或索引来源'},spider:{label:'Spider / 可执行来源',description:'JS / CatVod / JAR / Plugin，执行前需审核代码并批准版本'}};function groupKey(kind:SourceKind):GroupKey{if(kind==='T0_XML'||kind==='T1_JSON'||kind==='T4_EXT')return'api';if(kind==='T3_XYQ'||kind==='T3_XBPQ'||kind==='DRIVE_ALIST')return'rule';return'spider';}const sourceGroups=computed(()=>{const ranks=new Map<string,number>();sourceOrder.value.forEach((id,index)=>{if(!ranks.has(id))ranks.set(id,index);});return Object.entries(groupMeta).map(([key,meta])=>({key:key as GroupKey,...meta,items:sources.value.filter(source=>groupKey(source.kind)===key).sort((a,b)=>{return(ranks.get(a.id)??999999)-(ranks.get(b.id)??999999);})})).filter(group=>group.items.length>0);});
const liveOriginMeta={local:{label:'本地播放列表',origins:['local-file']},remote:{label:'网络播放列表',origins:['remote-playlist']},tvbox:{label:'TVBox / FongMi 配置直播',origins:['tvbox']},other:{label:'其他直播来源',origins:['manual',undefined]}} as const;const liveGroups=computed(()=>Object.entries(liveOriginMeta).map(([key,meta])=>({key,label:meta.label,items:visibleItems(liveSources.value).filter(item=>(meta.origins as readonly (string|undefined)[]).includes(item.origin))})).filter(group=>group.items.length));
interface ImportGroup{id:string;label:string;importedAt:string;pointSources:SourceConfig[];liveSources:LiveSourceConfig[];compatible:number;incompatible:number;pending:number;}
const importGroups=computed<ImportGroup[]>(()=>{const groups=new Map<string,ImportGroup>();const ensure=(id:string,label:string,importedAt:string)=>{let group=groups.get(id);if(!group){group={id,label,importedAt,pointSources:[],liveSources:[],compatible:0,incompatible:0,pending:0};groups.set(id,group);}return group;};for(const source of sources.value)if(source.importGroupId)ensure(source.importGroupId,source.sourceLabel??'导入配置',source.importedAt??'').pointSources.push(source);for(const source of liveSources.value)if(source.importGroupId)ensure(source.importGroupId,source.sourceLabel??source.name,source.importedAt??'').liveSources.push(source);for(const group of groups.values())for(const source of [...group.pointSources,...group.liveSources]){const item=healthMap.value.get(source.id);if(!item)group.pending+=1;else if(item.ok)group.compatible+=1;else group.incompatible+=1;}return[...groups.values()].sort((a,b)=>b.importedAt.localeCompare(a.importedAt));});
const importGroupLabels=computed(()=>new Map(importGroups.value.map(group=>[group.id,group.label])));
const liveSourceIds=computed(()=>new Set(liveSources.value.map(source=>source.id)));
const compatibilityFilter=ref<'all'|'compatible'|'incompatible'|'pending'|'partial'|'runtime'>('all');const compatibilityRows=computed(()=>{const rows=[...sources.value.map(source=>({source,type:'点播',group:source.importGroupId?(importGroupLabels.value.get(source.importGroupId)??'导入配置'):'未归组'})),...liveSources.value.map(source=>({source,type:'直播',group:source.importGroupId?(importGroupLabels.value.get(source.importGroupId)??'导入配置'):'未归组'}))].map(row=>({...row,health:healthMap.value.get(row.source.id)}));const labels={compatible:['接口通过','列表已解析'],incompatible:['检查失败','不兼容'],pending:['待验证','待重试','待授权'],partial:['部分兼容'],runtime:['需要运行时']};return compatibilityFilter.value==='all'?rows:rows.filter(row=>labels[compatibilityFilter.value as keyof typeof labels].includes(sourceCapabilities(row.health,row.type==='直播').label));});
function originLabel(source:LiveSourceConfig){if(source.origin==='local-file')return'本地文件';if(source.origin==='remote-playlist')return'网络 URL';if(source.origin==='tvbox')return'TVBox/FongMi';return'手工';}
const editDraft=reactive({id:'',name:'',endpoint:'',ext:'',jar:''});const editLiveDraft=reactive({id:'',name:'',epg:'',userAgent:''});const editOpen=ref(false);const editLiveOpen=ref(false);
function openEdit(source:SourceConfig){editDraft.id=source.id;editDraft.name=source.name;editDraft.endpoint=source.endpoint;editDraft.ext=source.ext??'';editDraft.jar=source.jar??'';editOpen.value=true;}
async function saveEdit(){error.value='';const source=sources.value.find(item=>item.id===editDraft.id);if(!source){editOpen.value=false;return;}try{await window.desktop.source.save({...source,name:editDraft.name.trim()||source.name,endpoint:editDraft.endpoint.trim()||source.endpoint,...(editDraft.ext.trim()?{ext:editDraft.ext.trim()}:{ext:undefined}),...(editDraft.jar.trim()?{jar:editDraft.jar.trim()}:{jar:undefined})});editOpen.value=false;importMessage.value=`来源「${source.name}」已保存。`;await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
function openEditLive(source:LiveSourceConfig){editLiveDraft.id=source.id;editLiveDraft.name=source.name;editLiveDraft.epg=source.epg??'';editLiveDraft.userAgent=Object.entries(source.headers??{}).find(([key])=>key.toLowerCase()==='user-agent')?.[1]??'';editLiveOpen.value=true;}
async function saveEditLive(){error.value='';const source=liveSources.value.find(item=>item.id===editLiveDraft.id);if(!source){editLiveOpen.value=false;return;}try{const headers={...source.headers};for(const key of Object.keys(headers))if(key.toLowerCase()==='user-agent')delete headers[key];if(editLiveDraft.userAgent.trim())headers['User-Agent']=editLiveDraft.userAgent.trim();await window.desktop.live.saveSource({...source,name:editLiveDraft.name.trim()||source.name,epg:editLiveDraft.epg.trim()||undefined,headers:Object.keys(headers).length?headers:undefined});editLiveOpen.value=false;importMessage.value=`直播来源「${source.name}」已保存。`;await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
type DeleteDraft={kind:'vod'|'live'|'group';id:string;name:string;confirmText:string;counts:Array<{label:string;count:number|null}>};
const deleteDraft=ref<DeleteDraft|null>(null);
const vodSourcesHeading=ref<HTMLElement|null>(null);
