function syncDialog(element:unknown,open:boolean){
  if(!(element instanceof HTMLDialogElement))return;
  if(open&&!element.open)element.showModal();
  else if(!open&&element.open)element.close();
}
function deleteReady(){return Boolean(deleteDraft.value&&deleteDraft.value.confirmText===deleteDraft.value.name);}
async function requestRemove(source:SourceConfig){error.value='';try{const [favorites,history]=await Promise.all([listVodFavorites().catch(()=>null),window.desktop.history.list(1000).catch(()=>null)]);deleteDraft.value={kind:'vod',id:source.id,name:source.name,confirmText:'',counts:[{label:'点播来源本身',count:1},{label:'关联收藏',count:favorites?.filter(item=>item.sourceId===source.id).length??null},{label:'最近200条历史中的关联项',count:history?.filter(item=>item.sourceId===source.id).length??null}]};}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function requestRemoveLive(source:LiveSourceConfig){error.value='';try{const [channels,favorites,reservations,epg]=await Promise.all([window.desktop.live.channels(source.id).catch(()=>null),window.desktop.live.favorites().then(items=>items.filter(item=>item.liveSourceId===source.id)).catch(()=>null),window.desktop.reservation.list().then(items=>items.filter(item=>item.liveSourceId===source.id)).catch(()=>null),window.desktop.epg.list(source.id).catch(()=>null)]);deleteDraft.value={kind:'live',id:source.id,name:source.name,confirmText:'',counts:[{label:'直播频道',count:channels?.reduce((sum,group)=>sum+group.channels.length,0)??null},{label:'直播收藏',count:favorites?.length??null},{label:'节目预约',count:reservations?.length??null},{label:'EPG 节目单条目',count:epg?.length??null},...(source.origin==='local-file'?[{label:'托管的播放列表文件',count:1}]:[])]};}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function deleteImportGroup(group:ImportGroup){
  const removedIds=new Set(group.pointSources.map(item=>item.id));
  const result=await window.desktop.source.removeImportGroup(group.id);
  if(removedIds.has(localStorage.getItem('vod.sourceId')??''))localStorage.removeItem('vod.sourceId');
  if(group.liveSources.some(item=>item.id===localStorage.getItem('live.sourceId')))localStorage.removeItem('live.sourceId');
  const failures=result.managedFileFailures??[];
  importMessage.value=failures.length
    ?`导入源「${group.label}」的记录已删除：${result.pointSources} 个点播、${result.liveSources} 个直播；托管文件清理未全部完成。`
    :`导入源「${group.label}」已删除：${result.pointSources} 个点播、${result.liveSources} 个直播及全部关联数据。`;
  await reload();
  if(failures.length)error.value=[error.value,`${failures.length} 个托管播放列表文件未能删除。来源记录已删除，原始导入文件不受影响。残留来源ID：${failures.map(item=>item.sourceId).join('、')}；请保留诊断日志以处理文件清理问题。`].filter(Boolean).join('；');
}
async function requestRemoveGroup(group:ImportGroup){if(checkingGroups.value.has(group.id)||groupDeleteBusy.value.has(group.id))return;const total=group.pointSources.length+group.liveSources.length;if(!window.confirm(`确认一键删除导入源「${group.label}」？\n\n将删除 ${group.pointSources.length} 个点播来源、${group.liveSources.length} 个直播来源（共 ${total} 个）以及关联的兼容性、历史、收藏、EPG 和预约数据。此操作不可恢复。`))return;const next=new Set(groupDeleteBusy.value);next.add(group.id);groupDeleteBusy.value=next;error.value='';importMessage.value=`正在删除导入源「${group.label}」…`;try{await deleteImportGroup(group);}catch(value){error.value=value instanceof Error?value.message:String(value);importMessage.value=`删除导入源「${group.label}」失败。`;}finally{const done=new Set(groupDeleteBusy.value);done.delete(group.id);groupDeleteBusy.value=done;}}
async function confirmDelete(){
  const draft=deleteDraft.value;if(!draft||!deleteReady())return;deleteDraft.value=null;
  try{
    if(draft.kind==='vod'){
      const source=sources.value.find(item=>item.id===draft.id);
      if(!source)throw new Error('点播来源不存在或已经删除');
      await remove(source);
    }else if(draft.kind==='live'){
      const source=liveSources.value.find(item=>item.id===draft.id);
      if(!source)throw new Error('直播来源不存在或已经删除');
      await removeLive(source);
    }else{
      const group=importGroups.value.find(item=>item.id===draft.id);
      if(!group)throw new Error('导入源不存在或已经删除');
      await deleteImportGroup(group);
    }
    await nextTick();
    if(document.activeElement===document.body){
      const heading=draft.kind==='live'?liveSourcesHeading.value:vodSourcesHeading.value;
      heading?.focus();
    }
  }catch(value){error.value=value instanceof Error?value.message:String(value);}
}
const bulkHealthBusy=ref(false);const bulkHealthProgress=ref('');let bulkHealthCancel=false;
async function runBulkHealth(){
  if(bulkHealthBusy.value){bulkHealthCancel=true;bulkHealthProgress.value='正在停止：等待当前检测结束，不再启动后续检测。';return;}
  const targets=sources.value.filter(item=>item.enabled);
  if(!targets.length){error.value='没有已启用的点播来源可检测。';return;}
  bulkHealthCancel=false;bulkHealthBusy.value=true;error.value='';let completed=0;
  try{
    for(const source of targets){
      if(bulkHealthCancel)break;
      bulkHealthProgress.value=`健康检测中 ${completed+1}/${targets.length} · ${source.name}`;
      const ownsMarker=!auditing.value.has(source.id);
      if(ownsMarker)auditing.value=new Set([...auditing.value,source.id]);
      try{audit.value=await window.desktop.source.audit(source.id);health.value=await window.desktop.source.health();}
      catch(value){error.value=value instanceof Error?value.message:String(value);}
      finally{completed++;if(ownsMarker){const done=new Set(auditing.value);done.delete(source.id);auditing.value=done;}}
    }
    bulkHealthProgress.value=bulkHealthCancel?`已取消后续检测（已处理 ${completed}/${targets.length}）`:`健康检测完成：${targets.length} 个来源`;
    importMessage.value=bulkHealthProgress.value;
  }finally{bulkHealthBusy.value=false;}
}
async function reload(clearError=true){
  const generation=++reloadGeneration;
  loading.value=true;if(clearError)error.value='';
  try{
    const results=await Promise.allSettled([window.desktop.source.list(),window.desktop.live.listSources(),window.desktop.source.health(),window.desktop.settings.list(),window.desktop.source.executableStatus()]);
    if(generation!==reloadGeneration)return;
    const [point,live,healthResult,settingsResult,trust]=results;
    if(point.status==='fulfilled')sources.value=retainUnchangedRows(sources.value,point.value,'id');
    if(live.status==='fulfilled')liveSources.value=retainUnchangedRows(liveSources.value,live.value,'id');
    if(healthResult.status==='fulfilled')health.value=retainUnchangedRows(health.value,healthResult.value,'sourceId');
    if(trust.status==='fulfilled')executableStates.value=retainUnchangedRows(executableStates.value,trust.value,'sourceId');
    const failed=results.filter(item=>item.status==='rejected');
    if(failed.length)error.value=failed.map(item=>String(item.reason instanceof Error?item.reason.message:item.reason)).join('；');
    if(settingsResult.status==='fulfilled')try{const parsed=JSON.parse(settingsResult.value['source.order']??'[]') as unknown;const order=Array.isArray(parsed)?parsed.filter((item):item is string=>typeof item==='string'):[];if(JSON.stringify(order)!==JSON.stringify(sourceOrder.value))sourceOrder.value=order;}catch{if(sourceOrder.value.length)sourceOrder.value=[];}
  }catch(value){if(generation===reloadGeneration)error.value=value instanceof Error?value.message:String(value);}
  finally{if(generation===reloadGeneration)loading.value=false;}
}
function retainUnchangedRows<T>(previous:T[],incoming:T[],key:keyof T):T[]{
  const existing=new Map(previous.map(item=>[item[key],item]));
  const next=incoming.map(item=>{
    const old=existing.get(item[key]);
    return old!==undefined&&JSON.stringify(old)===JSON.stringify(item)?old:item;
  });
  return next.length===previous.length&&next.every((item,index)=>item===previous[index])?previous:next;
}
function startSourceDrag(source:SourceConfig,event:DragEvent){
  if(sourceOrderBusy.value){event.preventDefault();return;}
  draggedSourceId.value=source.id;
  if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',source.id);}
}
async function stepSource(source:SourceConfig,direction:-1|1,event:MouseEvent){
  if(sourceOrderBusy.value)return;
  const items=sourceGroups.value.find(group=>group.key===groupKey(source.kind))?.items??[];
  const target=items[items.findIndex(item=>item.id===source.id)+direction];
  if(!target)return;
  const button=event.currentTarget as HTMLButtonElement;
  const hadFocus=document.activeElement===button;
  const tableGroup=button.closest('tbody');
  draggedSourceId.value=source.id;await moveSource(target.id);
  await nextTick();
  if(!hadFocus||(document.activeElement!==document.body&&document.activeElement!==button))return;
  const rowButton=button.isConnected
    ?button.parentElement?.querySelector<HTMLButtonElement>('button:not(:disabled)')
    :null;
  const pageSelect=tableGroup?.querySelector<HTMLSelectElement>('.source-pagination select');
  const destination=button.isConnected&&!button.disabled?button:rowButton??pageSelect??vodSourcesHeading.value;
  if(destination?.isConnected)destination.focus();
}
async function moveSource(targetId:string){
  const sourceId=draggedSourceId.value;draggedSourceId.value='';
  if(sourceOrderBusy.value||!sourceId||sourceId===targetId)return;
  const source=sources.value.find(item=>item.id===sourceId),target=sources.value.find(item=>item.id===targetId);
  if(!source||!target||groupKey(source.kind)!==groupKey(target.kind))return;
  const previous=[...sourceOrder.value],ids=new Set(sources.value.map(item=>item.id));
  const order=[...new Set([...previous,...ids])].filter(id=>ids.has(id));
  const from=order.indexOf(sourceId),to=order.indexOf(targetId);
  order.splice(from,1);order.splice(to,0,sourceId);sourceOrder.value=order;sourceOrderBusy.value=true;error.value='';
  try{const ok=await window.desktop.settings.set('source.order',JSON.stringify(order));if(!ok)throw new Error('来源排序未确认保存');importMessage.value='来源顺序已保存。';}
  catch(value){sourceOrder.value=previous;error.value=value instanceof Error?value.message:String(value);}
  finally{sourceOrderBusy.value=false;}
}
async function addSource(){error.value='';try{const executable=isExecutable(draft.kind);await window.desktop.source.save({id:crypto.randomUUID(),name:draft.name.trim(),endpoint:draft.endpoint.trim(),kind:draft.kind,enabled:!executable,trust:executable?'B':'A',...(draft.ext.trim()?{ext:draft.ext.trim()}:{}),...(draft.jar.trim()?{jar:draft.jar.trim()}:{})});draft.name='';draft.endpoint='';draft.ext='';draft.jar='';importMessage.value=executable?'可执行来源已添加并保持停用；请导出代码审核、批准该版本后启用。':'';await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function toggle(source:SourceConfig){error.value='';try{const next=!source.enabled;await window.desktop.source.save({...source,enabled:next});importMessage.value=`点播来源「${source.name}」已${next?'启用':'停用'}。`;await reload();}catch(value){error.value=`切换「${source.name}」失败：`+(value instanceof Error?value.message:String(value));}}async function toggleLive(source:LiveSourceConfig){error.value='';try{const next=!source.enabled;await window.desktop.live.saveSource({...source,enabled:next});importMessage.value=`直播来源「${source.name}」已${next?'启用':'停用'}。`;await reload();}catch(value){error.value=`切换「${source.name}」失败：`+(value instanceof Error?value.message:String(value));}}
async function remove(source:SourceConfig){const ok=await window.desktop.source.remove(source.id);if(!ok)throw new Error(`点播来源「${source.name}」不存在或删除未确认`);importMessage.value=`点播来源「${source.name}」及其关联数据已删除。`;await reload();}async function removeLive(source:LiveSourceConfig){const ok=await window.desktop.live.removeSource(source.id);if(!ok)throw new Error(`直播来源「${source.name}」不存在或删除未确认`);importMessage.value=`直播来源「${source.name}」已级联删除（频道、收藏、EPG、预约与托管文件）。`;await reload();}
function dialogEscape(event:KeyboardEvent){if(event.key!=='Escape')return;deleteDraft.value=null;editOpen.value=false;editLiveOpen.value=false;}
const onlyUnhealthy=ref(false);
const sourcePage=ref<HTMLElement|null>(null);
const sourcePages=reactive<Record<string,number>>({});
const sourceSearch=ref('');
function matchesSource(source:{name?:string;endpoint?:string;url?:string}){const query=sourceSearch.value.trim().toLocaleLowerCase();return !query||[source.name,source.endpoint,source.url].some(value=>value?.toLocaleLowerCase().includes(query));}
function pageFor(key:string,total:number){return clampSourcePage(sourcePages[key]??1,total);}
function setSourcePage(key:string,page:number){sourcePages[key]=page;draggedSourceId.value='';}
watch([onlyUnhealthy,sourceSearch,compatibilityFilter],()=>{for(const key of Object.keys(sourcePages))delete sourcePages[key];});
const filteredCompatibilityRows=computed(()=>compatibilityRows.value.filter(row=>matchesSource(row.source)));
const renderedCompatibilityRows=computed(()=>sourcePageItems(filteredCompatibilityRows.value,sourcePages.compatibility??1));
function renderedItems<T extends {id:string;name?:string;endpoint?:string;url?:string}>(items:T[],key:string):T[]{return sourcePageItems(visibleItems(items),sourcePages[key]??1);}
function visibleItems<T extends {id:string;name?:string;endpoint?:string;url?:string}>(items:T[]):T[]{return items.filter(item=>matchesSource(item)&&(!onlyUnhealthy.value||healthMap.value.get(item.id)?.ok===false));}
onMounted(()=>{window.addEventListener('keydown',dialogEscape);if(route.query.filter==='unhealthy')onlyUnhealthy.value=true;void reload();});
onBeforeUnmount(()=>{bulkHealthCancel=true;reloadGeneration++;window.removeEventListener('keydown',dialogEscape);});
function compatibilitySummary(items:{compatible:boolean}[]|undefined){const values=items??[],compatible=values.filter(item=>item.compatible).length;return`接口/列表检查通过 ${compatible} 个，未通过 ${values.length-compatible} 个`;}
async function importConfig(){error.value='';importMessage.value='正在导入并逐来源检查兼容性…';try{const result=await window.desktop.config.importText(importText.value);importMessage.value='已导入 '+result.sources.length+' 个点播源、'+result.liveSources.length+' 个直播源；'+compatibilitySummary(result.compatibility)+(result.warnings.length?'；'+result.warnings.join('；'):'');importText.value='';toast.success('配置导入完成',importMessage.value);await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);toast.error('配置导入失败',error.value);}}
async function importConfigFile(){error.value='';importMessage.value='正在导入并逐来源检查兼容性…';try{const result=await window.desktop.config.importFile();if(result.canceled){importMessage.value='已取消导入本地配置。';return;}if(result.result){importMessage.value='本地配置已导入：'+result.result.sources.length+' 个点播源、'+result.result.liveSources.length+' 个直播源；'+compatibilitySummary(result.result.compatibility);await reload();}}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function importLiveFile(){error.value='';importMessage.value='正在导入并检查直播来源兼容性…';try{const result=await window.desktop.live.importFile();if(result.canceled){importMessage.value='已取消导入直播列表。';return;}if(!result.canceled){importMessage.value='本地直播列表已导入，共 '+(result.channelCount??0)+' 个频道；'+compatibilitySummary(result.compatibility);await reload();}}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function importLiveUrl(){error.value='';importMessage.value='正在导入并检查直播来源兼容性…';try{const result=await window.desktop.live.importUrl({url:liveDraft.url.trim(),...(liveDraft.name.trim()?{name:liveDraft.name.trim()}:{}),...(liveDraft.epg.trim()?{epg:liveDraft.epg.trim()}:{}),...(liveDraft.userAgent.trim()?{userAgent:liveDraft.userAgent.trim()}:{})});importMessage.value='网络直播列表已导入，共 '+result.channelCount+' 个频道；'+compatibilitySummary(result.compatibility);liveDraft.name='';liveDraft.url='';liveDraft.epg='';liveDraft.userAgent='';await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function checkGroup(group:ImportGroup){const next=new Set(checkingGroups.value);next.add(group.id);checkingGroups.value=next;error.value='';importMessage.value=`正在重新检查「${group.label}」的 ${group.pointSources.length+group.liveSources.length} 个来源…`;try{const results=await window.desktop.source.checkImportGroup(group.id);importMessage.value=`「${group.label}」检查完成：${compatibilitySummary(results)}`;health.value=await window.desktop.source.health();}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{const done=new Set(checkingGroups.value);done.delete(group.id);checkingGroups.value=done;}}
async function executableAction(source:SourceConfig,action:'review'|'approve'|'revoke'){const next=new Set(executableBusy.value);next.add(source.id);executableBusy.value=next;error.value='';try{if(action==='review'){const result=await window.desktop.source.reviewExecutable(source.id);importMessage.value=result.canceled?'已取消导出':`代码已导出供审核：${result.path??''}。完成文件审核后点击“批准已审核版本”。`;}else if(action==='approve'){const result=await window.desktop.source.approveExecutable(source.id);importMessage.value=result.approved?'此代码版本已获执行授权；代码或配置更新后需要重新审核。':'未批准执行';}else{await window.desktop.source.revokeExecutable(source.id);importMessage.value='执行授权已撤销，现有来源运行时已停止。';}await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{const done=new Set(executableBusy.value);done.delete(source.id);executableBusy.value=done;}}
async function runAudit(source:SourceConfig){const next=new Set(auditing.value);next.add(source.id);auditing.value=next;error.value='';try{audit.value=await window.desktop.source.audit(source.id);health.value=await window.desktop.source.health();}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{const done=new Set(auditing.value);done.delete(source.id);auditing.value=done;}}
async function exportAudit(sourceId:string){error.value='';try{const result=await window.desktop.source.exportAudit(sourceId);importMessage.value=result.canceled?'已取消导出':`审计报告已导出：${result.path??''}`;}catch(value){error.value=value instanceof Error?value.message:String(value);}}
function fillExample(){importText.value='https://raw.githubusercontent.com/cwe88108/free-new-desk-public/main/examples/tvbox-sample.json';importMessage.value='这是本项目维护的最小 TVBox 示例配置；导入远程配置前仍会要求确认域名。';}
async function copySource(source:SourceConfig|LiveSourceConfig){
  const local=source.endpoint.startsWith('fnd-local://');
  const value=local?source.sourceLabel:source.endpoint;
  if(!value)return;
  error.value='';
  importMessage.value='';
  try{
    const ok=await window.desktop.app.action({copy:value});
    if(!ok)throw new Error('系统未确认写入剪贴板');
    importMessage.value=local?'来源文件路径已复制':'来源地址已复制';
  }catch(errorValue){error.value='复制来源地址失败：'+(errorValue instanceof Error?errorValue.message:String(errorValue));}
}
function compatibilityTip(message:string|undefined){if(!message)return'';if(/SOURCE_EXECUTABLE_NOT_APPROVED/i.test(message))return'先导出来源代码、规则和依赖完成审核，再批准当前版本执行。';if(/ClassNotFoundException/i.test(message))return'配置指定的 Spider 类不在当前 JAR 中，请更换匹配的 spider JAR 或停用该来源。';if(/timeout|timed out/i.test(message))return'来源响应超时，可检查网络、UA/Referer 或降低该来源优先级。';if(/403|forbidden/i.test(message))return'来源拒绝访问，通常需要正确的 User-Agent、Referer、Cookie 或来源已失效。';if(/format|parse/i.test(message))return'返回格式与声明类型不匹配，请核对接口类型或规则。';return message;}
function compatibilityLabel(sourceId:string){return sourceCapabilities(healthMap.value.get(sourceId),liveSourceIds.value.has(sourceId)).label;}
function compatibilityClass(sourceId:string){const label=compatibilityLabel(sourceId);return{safe:label==='接口通过'||label==='列表已解析',danger:label==='检查失败'||label==='不兼容',pending:label!=='接口通过'&&label!=='列表已解析'&&label!=='检查失败'&&label!=='不兼容'};}
function confirmBulk(items:SourceConfig[],enabled:boolean):boolean{return true;}
async function applyBulk(pointItems:SourceConfig[],liveItems:LiveSourceConfig[],enabled:boolean,label:string){bulkBusy.value=true;error.value='';try{const pointTargets=pointItems.filter(source=>source.enabled!==enabled),liveTargets=liveItems.filter(source=>source.enabled!==enabled);const result=await window.desktop.source.setEnabledBulk({vodSourceIds:pointTargets.map(item=>item.id),liveSourceIds:liveTargets.map(item=>item.id),enabled}),failedIds=new Set(result.failed.map(item=>item.sourceId));for(const source of pointTargets)if(!failedIds.has(source.id))source.enabled=enabled;for(const source of liveTargets)if(!failedIds.has(source.id))source.enabled=enabled;importMessage.value=label+'完成：修改 '+result.changed+' 个，未变化 '+result.unchanged+' 个，失败 '+result.failed.length+' 个。';if(result.failed.length)error.value=result.failed.slice(0,3).map(item=>item.sourceId+'：'+item.reason).join('；');await reload(false);}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{bulkBusy.value=false;}}
async function setPointSources(items:SourceConfig[],enabled:boolean){await applyBulk(items,[],enabled,enabled?'启动本组':'停用本组');}
async function setLiveSources(enabled:boolean){await applyBulk([],liveSources.value,enabled,enabled?'启动全部直播来源':'停用全部直播来源');}
async function setAll(enabled:boolean){await applyBulk(sources.value,liveSources.value,enabled,enabled?'全部启动':'全部停用');}
async function setCompatibilitySources(compatible:boolean,enabled:boolean,label:string){const ids=new Set(health.value.filter(item=>item.ok===compatible).map(item=>item.sourceId));const point=sources.value.filter(item=>ids.has(item.id)),live=liveSources.value.filter(item=>ids.has(item.id));if(point.length+live.length===0){importMessage.value=compatible?'没有检查通过的来源可启用。':'没有检查失败的来源可停用。';return;}await applyBulk(point,live,enabled,label);}
</script>

<template><section ref="sourcePage" class="page sources-page"><section class="page-banner"><div><h1>来源管理</h1><p>点播配置与 IPTV 播放列表分开管理；直播频道始终归属于导入来源。</p></div><blockquote>广收并蓄，择善而从。<br/><span>优质来源，让体验更稳定。</span></blockquote><div class="banner-stilllife"><i/><b/></div></section>
<div class="source-top-grid"><article class="panel import-console"><div class="panel-heading"><div><span class="panel-kicker">导入中心</span><h2>配置 / 本地 IPTV / 网络 IPTV</h2></div></div><div class="import-tabs"><button :class="{active:importTab==='config'}" @click="importTab='config'">TVBox 配置</button><button :class="{active:importTab==='local-live'}" @click="importTab='local-live'">本地直播列表</button><button :class="{active:importTab==='remote-live'}" @click="importTab='remote-live'">网络直播列表</button></div><template v-if="importTab==='config'"><textarea v-model="importText" rows="4" placeholder="输入 TVBox / FongMi 配置 URL，或直接粘贴 JSON"></textarea><div class="row-actions"><button class="primary-button" :disabled="!importText.trim()" @click="importConfig">导入配置</button><button class="secondary-button" @click="importConfigFile">选择本地配置</button><button class="text-link" @click="fillExample">示例</button><details class="inline-details"><summary>手工添加点播来源</summary><div class="manual-source-form"><input v-model="draft.name" placeholder="名称"/><select v-model="draft.kind"><option value="T1_JSON">CMS JSON</option><option value="T0_XML">CMS XML</option><option value="T4_EXT">Type4</option><option value="T3_JS">JS Spider / Drpy</option><option value="T3_XYQ">XYQ</option><option value="T3_XBPQ">XBPQ</option><option value="DRIVE_ALIST">Alist</option><option value="T3_JAR">Java JAR</option><option value="T3_PY">Python Spider（可信代码预览）</option><option value="PLUGIN">本地插件</option></select><input v-model="draft.endpoint" placeholder="API / Endpoint / Manifest"/><input v-model="draft.ext" placeholder="Ext / 规则 / JS URL"/><input v-if="draft.kind==='T3_JAR'" v-model="draft.jar" placeholder="JAR 路径或 URL"/><button class="secondary-button" :disabled="!draft.name.trim()||!draft.endpoint.trim()" @click="addSource">添加</button></div></details></div></template><template v-else-if="importTab==='local-live'"><div class="drop-import"><strong>M3U / M3U8 / TXT / JSON</strong><p>文件会复制到应用托管目录并作为独立直播来源。删除该来源会同步删除其频道、收藏、EPG/预约数据和托管文件。</p><button class="primary-button" @click="importLiveFile">选择本地播放列表</button></div></template><template v-else><div class="remote-live-form"><input v-model="liveDraft.name" placeholder="来源名称（可选）"/><input v-model="liveDraft.url" placeholder="https://example.com/playlist.m3u"/><input v-model="liveDraft.epg" placeholder="XMLTV EPG URL（可选）"/><input v-model="liveDraft.userAgent" placeholder="自定义 User-Agent（可选）"/><button class="primary-button" :disabled="!liveDraft.url.trim()" @click="importLiveUrl">导入网络播放列表</button></div></template><small class="helper-text">{{importMessage||'软件不预置第三方影视或直播内容；所有播放列表由用户自行导入。'}}</small></article><section class="source-summary"><article><small>全部来源</small><strong>{{totalCount}}</strong><span>点播 + 直播 · 100%</span></article><article><small>已启用</small><strong>{{enabledCount}}</strong><span>占全部来源 {{enabledPercent}}%</span></article><article><small>检查通过</small><strong>{{passedCount}}</strong><span>占全部来源 {{passedPercent}}%</span></article><article><small>待审核代码</small><strong>{{confirmCount}}</strong><span>外部执行授权 · {{confirmPercent}}%</span></article></section></div>
<div v-if="sourceStateBanner" class="panel source-state-banner" :data-state="sourceStateBanner.kind"><strong>{{sourceStateBanner.title}}</strong><span>{{sourceStateBanner.detail}}</span></div>
<section class="panel import-groups-panel"><div class="panel-heading"><div><span class="panel-kicker">导入源</span><h2>按导入批次管理与兼容性检查</h2></div><small>删除导入源会级联删除其全部点播、直播及关联数据</small></div><div v-if="loading&&totalCount===0" class="loading-panel">正在读取导入源…</div><div v-else-if="importGroups.length===0" class="compact-empty">现有旧来源没有导入批次信息；新导入配置会在这里统一管理。</div><div v-else class="import-group-list"><article v-for="group in importGroups" :key="group.id" class="import-group-card"><div class="import-group-copy"><strong>{{group.label}}</strong><small>{{group.importedAt?new Date(group.importedAt).toLocaleString():'导入时间未知'}} · 点播 {{group.pointSources.length}} · 直播 {{group.liveSources.length}}</small></div><div class="compatibility-summary"><span class="compat-badge compatible">通过 {{group.compatible}}</span><span class="compat-badge incompatible">未通过 {{group.incompatible}}</span><span v-if="group.pending" class="compat-badge pending">待检查 {{group.pending}}</span></div><div class="table-actions"><button :disabled="checkingGroups.has(group.id)||groupDeleteBusy.has(group.id)" @click="checkGroup(group)">{{checkingGroups.has(group.id)?'检查中…':'重新检查全部'}}</button><button class="danger-link" :disabled="checkingGroups.has(group.id)||groupDeleteBusy.has(group.id)" @click="requestRemoveGroup(group)">{{groupDeleteBusy.has(group.id)?'删除中…':'一键删除源'}}</button></div></article></div></section>
<div class="panel source-search"><label>筛选来源 <input v-model="sourceSearch" type="search" placeholder="输入来源名称或地址" aria-label="筛选来源名称或地址" /></label><small>筛选只影响列表显示；全部及本组操作仍作用于完整来源集合。</small></div>
<section class="panel compatibility-results-panel"><div class="panel-heading"><div><span class="panel-kicker">检查结果</span><h2>逐来源兼容性明细 · {{compatibilityRows.length}} 项</h2></div><div class="compat-filter"><button :class="{active:compatibilityFilter==='all'}" @click="compatibilityFilter='all'">全部</button><button :class="{active:compatibilityFilter==='compatible'}" @click="compatibilityFilter='compatible'">检查通过</button><button :class="{active:compatibilityFilter==='incompatible'}" @click="compatibilityFilter='incompatible'">检查失败</button><button :class="{active:compatibilityFilter==='pending'}" @click="compatibilityFilter='pending'">待验证</button><button :class="{active:compatibilityFilter==='partial'}" @click="compatibilityFilter='partial'">部分兼容</button><button :class="{active:compatibilityFilter==='runtime'}" @click="compatibilityFilter='runtime'">需运行时</button></div></div><SourcePager label="兼容性明细" :total="filteredCompatibilityRows.length" :page="pageFor('compatibility',filteredCompatibilityRows.length)" @change="setSourcePage('compatibility',$event)"/><div class="compatibility-table-wrap"><table class="source-table compatibility-table"><thead><tr><th>来源</th><th>类型</th><th>所属导入源</th><th>结果</th><th>阶段 / 耗时</th><th>原因与处理建议</th><th>检查时间</th></tr></thead><tbody><tr v-if="filteredCompatibilityRows.length===0"><td colspan="7" class="compact-empty">当前筛选下没有来源。</td></tr><tr v-for="row in renderedCompatibilityRows" :key="row.type+row.source.id" v-memo="[row.source,row.source.id,row.source.name,row.health,row.health?.checkedAt,row.health?.ok,row.health?.latencyMs,row.health?.retryable,row.health?.compatibilityStage,row.health?.failureReason,row.health?.message,row.health?.audit,row.group,row.type,liveSources]"><td><strong>{{row.source.name}}</strong><small>{{row.source.id}}</small></td><td>{{row.type}}</td><td><span class="group-label" :title="row.group">{{row.group}}</span></td><td><span class="compat-badge" :class="compatibilityClass(row.source.id)">{{compatibilityLabel(row.source.id)}}</span></td><td>{{row.health?.compatibilityStage??'—'}}<small v-if="row.health">{{row.health.latencyMs}}ms · {{row.health.retryable?'可重试':'已确认'}}</small></td><td><span class="compat-reason">{{compatibilityTip(row.health?.failureReason??row.health?.message)||'尚未执行兼容性检查'}}<small>{{sourceCapabilities(row.health,row.type==='直播').detail}}</small></span></td><td>{{row.health?.checkedAt?new Date(row.health.checkedAt).toLocaleString():'—'}}</td></tr></tbody></table></div></section>
<div class="bulk-toolbar panel"><div><span class="panel-kicker">全局控制</span><strong>一键启动 / 停用所有来源</strong></div><div class="row-actions"><button class="primary-button" :disabled="bulkBusy||totalCount===0" @click="setAll(true)">全部启动</button><button class="secondary-button" :disabled="bulkBusy||totalCount===0" @click="setAll(false)">全部停用</button><button class="secondary-button" :disabled="bulkBusy||passedCount===0" @click="setCompatibilitySources(true,true,'启用检查通过来源')">启用检查通过来源</button><button class="secondary-button" :disabled="bulkBusy||health.filter(item=>item.ok===false).length===0" @click="setCompatibilitySources(false,false,'停止检查失败来源')">停止检查失败来源</button><button class="secondary-button" :disabled="!bulkHealthBusy&&sources.length===0" :title="bulkHealthBusy?'等待当前检测结束后停止后续检测':''" @click="runBulkHealth">{{bulkHealthBusy?'停止检测':'健康检测（全部）'}}</button><button class="secondary-button" :disabled="bulkBusy" @click="reload()">刷新</button><label class="unhealthy-toggle"><input v-model="onlyUnhealthy" type="checkbox"/>仅显示异常来源</label></div><small v-if="bulkHealthProgress" class="health-progress">{{bulkHealthProgress}}</small></div><p v-if="error" class="error-banner">{{error}}</p>
<div class="source-workspace"><section class="panel source-table-panel"><div class="panel-heading"><div><span class="panel-kicker">点播来源</span><h2 id="vod-sources-heading" ref="vodSourcesHeading" tabindex="-1">按大类分组 · 共 {{sources.length}} 个</h2></div></div><div v-if="loading&&sources.length===0" class="loading-panel">正在读取来源…</div><div v-else-if="sources.length===0" class="compact-empty">尚未添加点播来源。</div><div v-else class="source-table-wrap"><table class="source-table"><thead><tr><th>来源名称</th><th>来源类型</th><th>配置 / 播放策略</th><th>信任等级</th><th>兼容性 / 评分</th><th>最后检查</th><th>启用</th><th>操作</th></tr></thead><template v-for="group in sourceGroups" :key="group.key"><tbody class="source-group-body"><tr class="source-group-row"><td colspan="8"><div class="source-group-heading"><div><strong>{{group.label}}</strong><small>{{group.description}} · {{group.items.length}} 个</small><SourcePager :label="group.label" :total="visibleItems(group.items).length" :page="pageFor('vod:'+group.key,visibleItems(group.items).length)" @change="setSourcePage('vod:'+group.key,$event)"/></div><div class="table-actions"><button :disabled="bulkBusy" @click="setPointSources(group.items,true)">启动本组</button><button :disabled="bulkBusy" @click="setPointSources(group.items,false)">停用本组</button></div></div></td></tr><tr v-for="source in renderedItems(group.items,'vod:'+group.key)" :key="source.id" v-memo="[source,source.name,source.kind,source.endpoint,source.enabled,source.searchable,source.configShell,source.playUrl,source.playerType,source.trust,healthMap.get(source.id),healthMap.get(source.id)?.checkedAt,healthMap.get(source.id)?.ok,healthMap.get(source.id)?.score,healthMap.get(source.id)?.latencyMs,healthMap.get(source.id)?.compatibilityStage,healthMap.get(source.id)?.retryable,healthMap.get(source.id)?.failureReason,healthMap.get(source.id)?.message,healthMap.get(source.id)?.audit,executableStateMap.get(source.id),executableStateMap.get(source.id)?.approved,executableStateMap.get(source.id)?.required,executableStateMap.get(source.id)?.reviewReady,auditing.has(source.id),executableBusy.has(source.id),sourceOrderBusy,group.items[0]?.id,group.items[group.items.length-1]?.id,liveSources]" @dragover.prevent @drop.prevent.stop="moveSource(source.id)"><td><span class="drag-handle" draggable="true" title="拖拽进行同组排序" @dragstart="startSourceDrag(source,$event)" @dragend="draggedSourceId=''">⋮⋮</span><strong>{{source.name}}</strong><small>{{source.searchable===false?'不参与搜索':'可搜索'}}</small><span class="source-order-actions"><button :aria-label="'上移来源 '+source.name" title="上移" :disabled="sourceOrderBusy||group.items[0]?.id===source.id" @click="stepSource(source,-1,$event)">↑</button><button :aria-label="'下移来源 '+source.name" title="下移" :disabled="sourceOrderBusy||group.items[group.items.length-1]?.id===source.id" @click="stepSource(source,1,$event)">↓</button></span></td><td>{{source.kind}}</td><td><small>配置：{{source.configShell??'plain'}}</small><small>{{source.playUrl?'Parser':'Resolver'}}{{source.playerType!==undefined?' · P'+source.playerType:''}}</small></td><td><span v-if="executableStateMap.get(source.id)?.required" class="trust-badge" :class="executableStateMap.get(source.id)?.approved?'safe':'warn'">{{executableStateMap.get(source.id)?.approved?'已授权版本':'待审核代码'}}</span><small v-if="executableStateMap.get(source.id)?.approved">加载代码时复核摘要</small><span v-else-if="!executableStateMap.get(source.id)?.required" class="trust-badge safe">内置接口</span></td><td><span class="compat-badge" :class="compatibilityClass(source.id)">{{compatibilityLabel(source.id)}}</span><details v-if="healthMap.get(source.id)?.audit" class="capability-details"><summary>接口能力明细</summary><p>{{sourceCapabilities(healthMap.get(source.id)).detail}}</p><div v-for="capability in sourceCapabilities(healthMap.get(source.id)).stages" :key="capability.key" :title="capability.message"><span>{{capability.label}}</span> · <strong>{{capability.state}}</strong><small v-if="capability.durationMs!==undefined">{{capability.durationMs}}ms</small></div></details><span v-if="healthMap.get(source.id)" class="score-bar" aria-hidden="true"><i :class="{good:(healthMap.get(source.id)?.score??0)>=80,warn:(healthMap.get(source.id)?.score??0)<80&&(healthMap.get(source.id)?.score??0)>=50}" :style="{width:(healthMap.get(source.id)?.score??0)+'%'}"/></span><small v-if="healthMap.get(source.id)">{{healthMap.get(source.id)?.score??0}} 分 · {{healthMap.get(source.id)?.compatibilityStage??'invoke'}} · {{healthMap.get(source.id)?.retryable?'可重试':'已确认'}}</small><small v-if="healthMap.get(source.id)?.failureReason" class="compat-tip">{{compatibilityTip(healthMap.get(source.id)?.failureReason)}}</small></td><td>{{healthMap.get(source.id)?.checkedAt?new Date(healthMap.get(source.id)!.checkedAt).toLocaleString():'—'}}</td><td><button type="button" class="switch" role="switch" :aria-checked="source.enabled" :aria-label="'点播来源启用状态：'+source.name" :class="{on:source.enabled}" @click="toggle(source)"><i/></button></td><td><div class="table-actions"><button :disabled="!source.enabled||auditing.has(source.id)" @click="runAudit(source)">{{auditing.has(source.id)?'审计中…':'审计'}}</button><button @click="toggle(source)">{{source.enabled?'停用':'启用'}}</button><button v-if="executableStateMap.get(source.id)?.required" :disabled="executableBusy.has(source.id)" @click="executableAction(source,'review')">导出代码审核</button><button v-if="executableStateMap.get(source.id)?.reviewReady" :disabled="executableBusy.has(source.id)" @click="executableAction(source,'approve')">批准已审核版本</button><button @click="openEdit(source)">编辑</button><details class="source-more"><summary aria-label="更多操作">…</summary><button @click="copySource(source)">复制地址</button><button @click="exportAudit(source.id)">导出审计</button><button v-if="executableStateMap.get(source.id)?.approved" :disabled="executableBusy.has(source.id)" @click="executableAction(source,'revoke')">撤销执行授权</button><button class="danger-link" @click="requestRemove(source)">删除</button></details></div></td></tr></tbody></template></table></div>
<div class="live-source-heading"><div><span class="panel-kicker">直播播放列表</span><h2 id="live-sources-heading" ref="liveSourcesHeading" tabindex="-1">按导入来源归组 · 共 {{liveSources.length}} 个</h2></div><div class="table-actions"><button :disabled="bulkBusy||liveSources.length===0" @click="setLiveSources(true)">启动直播</button><button :disabled="bulkBusy||liveSources.length===0" @click="setLiveSources(false)">停用直播</button></div></div><div v-if="!loading&&liveSources.length===0" class="compact-empty">当前没有直播播放列表。可从上方直接导入 M3U/M3U8/TXT/JSON。</div><template v-for="group in liveGroups" :key="group.key"><div class="playlist-group-title"><strong>{{group.label}}</strong><small>{{group.items.length}} 个来源</small></div><SourcePager :label="group.label" :total="visibleItems(group.items).length" :page="pageFor('live:'+group.key,visibleItems(group.items).length)" @change="setSourcePage('live:'+group.key,$event)"/><div class="source-table-wrap"><table class="source-table live-source-table"><thead><tr><th>直播来源</th><th>来源方式</th><th>地址 / 文件</th><th>兼容性</th><th>EPG</th><th>导入时间</th><th>启用</th><th>操作</th></tr></thead><tbody><tr v-for="source in renderedItems(group.items,'live:'+group.key)" :key="source.id" v-memo="[source,source.name,source.endpoint,source.enabled,source.sourceLabel,source.origin,source.epg,source.importedAt,healthMap.get(source.id),healthMap.get(source.id)?.checkedAt,healthMap.get(source.id)?.ok,healthMap.get(source.id)?.score,healthMap.get(source.id)?.latencyMs,healthMap.get(source.id)?.compatibilityStage,healthMap.get(source.id)?.retryable,healthMap.get(source.id)?.failureReason,healthMap.get(source.id)?.message,liveSources]"><td><strong>{{source.name}}</strong></td><td><span class="trust-badge safe">{{originLabel(source)}}</span></td><td><code :title="source.sourceLabel||source.endpoint">{{source.sourceLabel||source.endpoint}}</code></td><td><span class="compat-badge" :class="compatibilityClass(source.id)">{{compatibilityLabel(source.id)}}</span><small v-if="healthMap.get(source.id)">{{healthMap.get(source.id)?.compatibilityStage??'network'}} · {{healthMap.get(source.id)?.retryable?'可重试':'已确认'}}</small><small v-if="healthMap.get(source.id)?.failureReason" class="compat-tip">{{compatibilityTip(healthMap.get(source.id)?.failureReason)}}</small></td><td>{{source.epg?'已配置':'—'}}</td><td>{{source.importedAt?new Date(source.importedAt).toLocaleString():'—'}}</td><td><button type="button" class="switch" role="switch" :aria-checked="source.enabled" :aria-label="'直播来源启用状态：'+source.name" :class="{on:source.enabled}" @click="toggleLive(source)"><i/></button></td><td><div class="table-actions"><button @click="openEditLive(source)">编辑</button><button v-if="!source.endpoint.startsWith('fnd-local://')||source.sourceLabel" @click="copySource(source)">{{source.endpoint.startsWith('fnd-local://')?'复制文件路径':'复制地址'}}</button><button @click="toggleLive(source)">{{source.enabled?'停用':'启用'}}</button><button class="danger-link" @click="requestRemoveLive(source)">删除整个来源</button></div></td></tr></tbody></table></div></template></section>
<aside class="panel audit-rail"><div class="panel-heading"><div><span class="panel-kicker">来源审计</span><h2>{{audit?.sourceId??'选择来源审计'}}</h2></div><div v-if="audit" class="audit-heading-actions"><button class="text-link" @click="exportAudit(audit.sourceId)">导出报告</button><span class="trust-badge" :class="audit.ok?'safe':'warn'">{{audit.ok?'通过':'需检查'}}</span></div></div><template v-if="audit"><div class="audit-meta"><span>审计时间 {{new Date(audit.checkedAt).toLocaleString()}}</span><span>规则版本：Source Engine</span></div><p v-if="audit.notice" class="audit-notice">{{audit.notice}}</p><p class="audit-notice">接口审计仅验证首页、分类、搜索、详情和播放解析，不代表实际视频播放已经通过。</p><div class="audit-list"><div v-for="stage in audit.stages" :key="stage.stage"><span>{{stage.stage}}</span><b :class="{good:stage.ok}">{{stage.message?.startsWith('SKIPPED:')?'不适用':stage.message?.startsWith('NOT_RUN:')?'未执行':stage.ok?'通过':'失败'}}</b><small>{{stage.durationMs}}ms</small><p v-if="stage.message">{{stage.message}}</p><p v-if="!stage.ok&&compatibilityTip(stage.message)" class="compat-tip">建议：{{compatibilityTip(stage.message)}}</p></div></div></template><div v-else class="detail-empty"><span><AppIcon name="state-check" :size="22"/></span><h3>逐项确认来源与播放策略</h3><p>点击来源列表中的“审计”，验证分类、搜索、详情、播放地址解析与 Runtime 状态。</p></div></aside></div>

<dialog :ref="element=>syncDialog(element,editOpen)" @cancel.prevent="editOpen=false" class="source-dialog"><article v-if="editOpen"><h3>编辑点播来源</h3><label>名称<input v-model="editDraft.name" maxlength="80"/></label><label>接口地址<input v-model="editDraft.endpoint"/></label><label>Ext / 规则<input v-model="editDraft.ext"/></label><label>JAR<input v-model="editDraft.jar"/></label><div class="row-actions"><button class="primary-button" :disabled="!editDraft.name.trim()||!editDraft.endpoint.trim()" @click="saveEdit">保存</button><button class="secondary-button" @click="editOpen=false">取消</button></div></article></dialog>
<dialog :ref="element=>syncDialog(element,editLiveOpen)" @cancel.prevent="editLiveOpen=false" class="source-dialog"><article v-if="editLiveOpen"><h3>编辑直播来源</h3><label>名称<input v-model="editLiveDraft.name"/></label><label>EPG 地址<input v-model="editLiveDraft.epg" placeholder="XMLTV EPG URL（可留空）"/></label><label>User-Agent<input v-model="editLiveDraft.userAgent" placeholder="可留空"/></label><div class="row-actions"><button class="primary-button" :disabled="!editLiveDraft.name.trim()" @click="saveEditLive">保存</button><button class="secondary-button" @click="editLiveOpen=false">取消</button></div></article></dialog>
<dialog :ref="element=>syncDialog(element,Boolean(deleteDraft))" @cancel.prevent="deleteDraft=null" class="source-dialog danger-dialog"><article v-if="deleteDraft"><h3>删除{{deleteDraft.kind==='group'?'导入源':deleteDraft.kind==='vod'?'点播来源':'直播来源'}}「{{deleteDraft.name}}」</h3><p class="danger-note">此操作不可恢复，将清理全部关联数据。以下为预览统计；“未能读取”不表示没有关联数据，确认后仍会清理全部关联数据：</p><ul class="cascade-list"><li v-for="item in deleteDraft.counts" :key="item.label"><span>{{item.label}}</span><b>{{item.count??'未能读取'}}</b></li></ul><label>输入来源名称以确认：<input v-model="deleteDraft.confirmText" :placeholder="deleteDraft.name"/></label><div class="row-actions"><button class="secondary-button" @click="deleteDraft=null">取消</button><button class="danger-button" :disabled="!deleteReady()" @click="confirmDelete">确认删除</button></div></article></dialog></section></template>

