.score-bar i.good{background:var(--good)}
.score-bar i.warn{background:var(--gold)}
.unhealthy-toggle{display:flex;gap:5px;align-items:center;font-size:12px;white-space:nowrap}.health-progress{flex-basis:100%;color:var(--muted)}.source-dialog{position:fixed;inset:0;margin:auto;max-height:calc(100dvh - 48px);overflow:auto;width:min(460px,calc(100vw - 48px));max-width:460px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--text)}.source-dialog::backdrop{background:rgb(0 0 0 / 35%)}.source-dialog article{display:grid;gap:9px;padding:18px}.source-dialog label{display:grid;gap:4px;font-size:12px;color:var(--muted)}.danger-dialog{border-color:var(--danger)}.danger-note{margin:0;color:var(--danger);font-size:12px}.cascade-list{margin:0;padding:0;list-style:none;max-height:180px;overflow:auto}.cascade-list li{display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-top:1px solid var(--line-soft);font-size:12px}.cascade-list b{font-variant-numeric:tabular-nums}.danger-button{background:var(--danger);border-color:var(--danger);color:#fff}
</style>
